    /// <summary>
    /// OASIS provider for ENS (Ethereum Name Service).
    /// ENS names → Avatars. Subdomains → Holons.
    /// Reads ENS on-chain (Universal Resolver + registry) over Ethereum JSON-RPC; the hosted ENS subgraph was retired.
    /// </summary>
    public class ENSOASIS : OASISStorageProviderBase, IOASISStorageProvider, IOASISNETProvider
    {
        /// <summary>ENS registry on Ethereum mainnet.</summary>
        public const string MainnetRegistry = "0x00000000000c2e074ec69a0dfb2997ba6c7d2e1e";
        private const string OwnerSelector = "0x02571be3"; // owner(bytes32)
        private readonly HttpClient _httpClient;
        private bool _isActivated;

        public ENSOASIS(string rpcUrl = "https://ethereum-rpc.publicnode.com") : this(rpcUrl, null) { }

        internal ENSOASIS(string rpcUrl, HttpMessageHandler handler)
        {
            if (string.IsNullOrWhiteSpace(rpcUrl)) throw new ArgumentException("An Ethereum JSON-RPC endpoint is required.", nameof(rpcUrl));
            _httpClient = handler == null ? new HttpClient() : new HttpClient(handler, disposeHandler: false);
            _httpClient.BaseAddress = new Uri(rpcUrl);
            _httpClient.DefaultRequestHeaders.Add("Accept", "application/json");
            _httpClient.DefaultRequestHeaders.UserAgent.ParseAdd("NextGenSoftware-OASIS-ENSOASIS/2.0");
            ProviderName = "ENSOASIS";
            ProviderDescription = "Ethereum Name Service (ENS) names resolved on-chain through the Universal Resolver and registry.";
            ProviderType = new EnumValue<ProviderType>(Core.Enums.ProviderType.ENSOASIS);
            ProviderCategory = new EnumValue<ProviderCategory>(Core.Enums.ProviderCategory.Network);
            ProviderCapabilities.Add(new EnumValue<ProviderCategory>(Core.Enums.ProviderCategory.Blockchain));
        }

        private async Task<string> CallAsync(string to, string data)
        {
            var body = JsonSerializer.Serialize(new { jsonrpc = "2.0", id = 1, method = "eth_call", @params = new object[] { new { to, data }, "latest" } });
            using var response = await _httpClient.PostAsync("", new StringContent(body, Encoding.UTF8, "application/json"));
            var text = await response.Content.ReadAsStringAsync();
            if (!response.IsSuccessStatusCode) throw new HttpRequestException($"Ethereum eth_call failed: {(int)response.StatusCode} {response.ReasonPhrase}");
            using var document = JsonDocument.Parse(text);
            if (document.RootElement.TryGetProperty("error", out var error))
                throw new InvalidOperationException("ENS call reverted: " + (error.TryGetProperty("message", out var m) ? m.GetString() : error.GetRawText()));
            return document.RootElement.GetProperty("result").GetString();
        }

        private sealed record Name(string EnsName, string Address, string Resolver, string Owner);

        /// <summary>Resolves a name: its address record and resolver through the Universal Resolver, its owner from the registry.</summary>
        private async Task<Name> ResolveAsync(string providerKey)
        {
            var ensName = (providerKey ?? "").Trim().ToLowerInvariant().TrimEnd('/');
            if (ensName.Length == 0 || !ensName.Contains('.')) throw new ArgumentException("An ENS name such as 'name.eth' is required.", nameof(providerKey));
            var resolution = EnsUniversalResolverCodec.DecodeAddressResult(await CallAsync(EnsUniversalResolverCodec.MainnetProxy, EnsUniversalResolverCodec.EncodeAddressCall(ensName)));
            var ownerWord = await CallAsync(MainnetRegistry, OwnerSelector + Convert.ToHexString(EnsUniversalResolverCodec.Namehash(ensName)).ToLowerInvariant());
            return new Name(ensName, resolution.Address, resolution.Resolver, "0x" + ownerWord[^40..]);
        }

        public override async Task<OASISResult<bool>> ActivateProviderAsync()
        {
            var result = new OASISResult<bool>();
            try
            {
                // The registry must answer for the root node: proves the endpoint is Ethereum mainnet with ENS deployed.
                var root = await CallAsync(MainnetRegistry, OwnerSelector + new string('0', 64));
                if (root == null || root.Length != 66 || root[^40..] == new string('0', 40))
                {
                    OASISErrorHandling.HandleError(ref result, "ENSOASIS: the endpoint has no ENS registry (not Ethereum mainnet).");
                    return result;
                }
                _isActivated = true;
                IsProviderActivated = true;
                result.Result = true;
                result.Message = "ENSOASIS activated against the ENS registry.";
            }
            catch (Exception ex) { result.Exception = ex; OASISErrorHandling.HandleError(ref result, $"ENSOASIS activation failed: {ex.Message}"); }
            return result;
        }
        public override OASISResult<bool> ActivateProvider() => ActivateProviderAsync().Result;
        public override async Task<OASISResult<bool>> DeActivateProviderAsync() { _isActivated = false; IsProviderActivated = false; return new OASISResult<bool>(true); }
        public override OASISResult<bool> DeActivateProvider() => DeActivateProviderAsync().Result;

        public override async Task<OASISResult<IAvatar>> LoadAvatarByProviderKeyAsync(string providerKey, int version = 0)
        {
            var result = new OASISResult<IAvatar>();
            try
            {
                var name = await ResolveAsync(providerKey);
                var avatar = new Avatar { Username = name.EnsName };
                avatar.ProviderUniqueStorageKey[Core.Enums.ProviderType.ENSOASIS] = name.EnsName;
                avatar.MetaData["ens_name"] = name.EnsName;
                avatar.MetaData["ens_owner"] = name.Owner;
                avatar.MetaData["ens_resolved_address"] = name.Address;
                avatar.MetaData["ens_resolver"] = name.Resolver;
                result.Result = avatar;
                result.IsLoaded = true;
            }
            catch (Exception ex) { result.Exception = ex; OASISErrorHandling.HandleError(ref result, $"ENSOASIS: {ex.Message}"); }
            return result;
        }
        public override OASISResult<IAvatar> LoadAvatarByProviderKey(string providerKey, int version = 0) => LoadAvatarByProviderKeyAsync(providerKey, version).Result;

        public override Task<OASISResult<IEnumerable<IHolon>>> LoadHolonsForParentAsync(string providerKey, HolonType type = HolonType.All, bool loadChildren = true, bool recursive = true, int maxChildDepth = 0, int curentChildDepth = 0, bool continueOnError = true, bool loadChildrenFromProvider = false, int version = 0)
        {
            var result = new OASISResult<IEnumerable<IHolon>>();
            OASISErrorHandling.HandleError(ref result, "ENSOASIS: listing subdomains needs an ENS event indexer (the hosted ENS subgraph was retired); load a name instead.");
            return Task.FromResult(result);
        }
