        public override async Task<OASISResult<IHolon>> LoadHolonAsync(string providerKey, bool loadChildren = true, bool recursive = true, int maxChildDepth = 0, bool continueOnError = true, bool loadChildrenFromProvider = false, int version = 0)
        {
            var result = new OASISResult<IHolon>();
            try
            {
                var name = await ResolveAsync(providerKey);
                var holon = new Holon { Name = name.EnsName };
                holon.ProviderUniqueStorageKey[Core.Enums.ProviderType.ENSOASIS] = name.EnsName;
                holon.MetaData["ens_name"] = name.EnsName;
                holon.MetaData["ens_owner"] = name.Owner;
                holon.MetaData["ens_resolved_address"] = name.Address;
                holon.MetaData["ens_resolver"] = name.Resolver;
                result.Result = holon;
                result.IsLoaded = true;
            }
            catch (Exception ex) { result.Exception = ex; OASISErrorHandling.HandleError(ref result, $"ENSOASIS: {ex.Message}"); }
            return result;
        }
